actions.script:
ec.web?.response?.setHeader('Cache-Control', 'no-store, private')
ec.web?.response?.setHeader('Pragma', 'no-cache')
String company = related.userCompanyPartyId?.toString()
String allowedCompany = System.getenv('NASQO_ACCOUNTING_STAGE_COMPANY')
review = [available: false, status: 'NO_SAVED_REVIEW', readOnly: true]
if (allowedCompany && company == allowedCompany) {
    def helper = ec.resource.script(
        'component://growerp/service/NasqoSavedAccountingReview.groovy', null)
    review = helper.read(new File('/var/lib/nasqo-accounting-imports'), company)
}
